<main class="admin-shell"><aside class="admin-sidebar"><a class="brand" href="<?= base_url('admin') ?>"><span class="brand-mark">S</span><span>EUPHORIA <strong>OPS</strong></span></a><div class="admin-nav"><span class="eyebrow">COMMAND</span><a href="<?= base_url('admin') ?>">Overview</a><a href="<?= base_url('admin/events') ?>">Events</a><a class="admin-nav-active" href="<?= base_url('admin/registrations') ?>">Registrations</a><a href="<?= base_url('admin/attendance') ?>">Attendance</a></div><a href="<?= base_url('logout') ?>" class="admin-logout">Sign out</a></aside><section class="admin-content"><div class="admin-topbar"><div><span class="eyebrow accent">PARTICIPANT DIRECTORY</span><h1>Registrations</h1></div><span class="mono"><?= count($registrations) ?> TOTAL RECORDS</span></div><div class="admin-panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Participant</th><th>Registration</th><th>Event</th><th>Payment</th><th>Status</th><th>Finance action</th></tr></thead><tbody><?php foreach ($registrations as $registration): ?><tr data-testid="registration-table-row"><td><strong><?= esc($registration['participant_name']) ?></strong><span class="table-sub"><?= esc($registration['email']) ?></span></td><td class="mono"><?= esc($registration['registration_id']) ?></td><td><?= esc($registration['event_name']) ?><span class="table-sub"><?= esc($registration['category_name']) ?></span></td><td><?= esc(money($registration['total_amount'])) ?><span class="table-sub"><?= esc(strtoupper($registration['payment_status']??'NONE')) ?></span></td><td><span class="<?= status_class($registration['status']) ?>"><?= esc(strtoupper(str_replace('_',' ',$registration['status']))) ?></span></td><td><?php if($registration['status']==='pending_payment'&&array_intersect(session('roles')??[],['SUPER_ADMIN','FINANCE'])): ?><form method="post" action="<?= base_url('admin/payments/'.$registration['payment_id'].'/verify') ?>" data-testid="manual-payment-form"><input type="hidden" name="<?= csrf_token() ?>" value="<?= csrf_hash() ?>"><input type="hidden" name="reason" value="Offline/manual verification"><button class="table-action" type="submit" data-testid="manual-payment-verify-button">Mark paid</button></form><?php else: ?><span class="mono">—</span><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></div></section></main>